INSERT INTO reports (description, image_url, incident_type, severity, latitude, longitude, priority, mensaje_ciudadano)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
RETURNING id, description, image_url, incident_type, severity, latitude, longitude, priority, status, mensaje_ciudadano, created_at;

parameters.jsCode:
const body = $('Webhook').item.json.body || $('Webhook').item.json;


const traficoItems = $('Traer congestión cercana').all();
const trafico = traficoItems.length > 0 ? traficoItems[0].json : null;

// ↓↓↓ ESTA es la línea que reemplazas ↓↓↓
const contextoTrafico = (trafico && trafico.nombre)
  ? `Dato de tráfico cercano: ${trafico.nombre}, ${trafico.porcentaje_congestion}% de congestión (${trafico.estado}).`
  : "No hay datos de tráfico cercano disponibles.";
// ↑↑↑ ESTA es la línea que reemplazas ↑↑↑

const parts = [
  { text: `Eres un asistente de UrbanPulse que clasifica reportes ciudadanos de incidentes urbanos en Lima, Perú.
Analiza la descripción del ciudadano (y la imagen adjunta si existe) y clasifica el incidente. La prioridad debe ser un número del 1 al 5, donde 5 es la máxima urgencia y 1 la mínima.
Responde también con un mensaje breve y amable dirigido al ciudadano confirmando su reporte.
Descripción: "${body.description}"
${contextoTrafico}
Si la descripción menciona tráfico o congestión y tienes el dato de arriba, menciona el porcentaje exacto en tu mensaje al ciudadano.` }
];

if (body.image_base64) {
  parts.push({
    inline_data: {
      mime_type: "image/jpeg",
      data: body.image_base64
    }
  });
}

return {
  json: {
    contents: [{ parts }],
    generationConfig: {
      responseMimeType: "application/json",
      responseSchema: {
        type: "OBJECT",
        properties: {
          incident_type: { type: "STRING", enum: ["infraestructura_vial","alumbrado_publico","agua_saneamiento","residuos","arbolado_urbano","incendio","otro"] },
          severity: { type: "STRING", enum: ["baja","media","alta"] },
          priority: { type: "INTEGER" },
          mensaje_ciudadano: { type: "STRING" }
        },
        required: ["incident_type","severity","priority","mensaje_ciudadano"]
      }
    }
  }
};

const respuestaTexto = $json.candidates[0].content.parts[0].text;
const clasificacion = JSON.parse(respuestaTexto);

const body = $('Webhook').item.json.body || $('Webhook').item.json;

return {
  json: {
    description: body.description,
    image_url: null,
    incident_type: clasificacion.incident_type,
    severity: clasificacion.severity,
    priority: clasificacion.priority,
    mensaje_ciudadano: clasificacion.mensaje_ciudadano,
    latitude: body.latitude != null ? body.latitude : null,
    longitude: body.longitude != null ? body.longitude : null
  }
};
